package lk.sliit.nutricare.health;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="health_alerts")public class HealthAlert{@Id private UUID id;@Column(nullable=false)private UUID healthCheckId;@Column(nullable=false)private UUID patientId;@Column(nullable=false)private String priority;@Column(nullable=false)private String message;@Column(nullable=false)private String status;@Column(nullable=false)private Instant createdAt;protected HealthAlert(){}public HealthAlert(UUID checkId,UUID patientId,String priority,String message){id=UUID.randomUUID();healthCheckId=checkId;this.patientId=patientId;this.priority=priority;this.message=message;status="OPEN";createdAt=Instant.now();}public UUID getId(){return id;}public UUID getHealthCheckId(){return healthCheckId;}public UUID getPatientId(){return patientId;}public String getPriority(){return priority;}public String getMessage(){return message;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}}
